// SACAA PPL — AIR LAW question bank (MINED).
// Questions mined from the uploaded SACAA Air Law question banks (answer marked
// in the source). Mapped to PPL sections and deduped against the authored bank.

import type { AirLawQuestion } from "./airlaw-questions";

export const PPL_AIRLAW_MINED_QUESTIONS: AirLawQuestion[] = [
  { id: "PLAW-M-001", sectionId: "1", question: "Each contracting state shall provide an Aeronautical Information Service (AIS) in its territory and for areas in which the state is responsible for the Air Traffic Services outside its territory, and this shall include the preparation and origination of:", optionA: "Only NOTAM's and Circulars.", optionB: "Integrated Aeronautical Information Package.", optionC: "Only AIP and NOTAM's.", optionD: "AIP, NOTAM's, Circular and AIRAC", correctAnswer: "b", explanation: "ICAO Annex 15 requires the AIS to provide an Integrated Aeronautical Information Package (AIP, amendments, supplements, NOTAM, AIC, checklists).", difficulty: "medium" },
  { id: "PLAW-M-002", sectionId: "4", question: "According to SA-CATS 91.07.5, for a precision approach category I runway to be classified as having full facilities, the minimum length of HI/MI approach lighting required is:", optionA: "720 m", optionB: "1200m", optionC: "900m", optionD: "420m", correctAnswer: "a", explanation: "Per SA-CATS, a Cat I precision approach runway must have an RVR assessment system giving a minimum RVR capability of 720 m.", difficulty: "medium" },
  { id: "PLAW-M-003", sectionId: "4", question: "A double white cross displayed horizontally in the signal area means:", optionA: "Need special precautions while approaching for landing.", optionB: "The aerodrome is being used by gliders and that glider flights are being performed.", optionC: "An area unit for the movement of aircraft.", optionD: "Special precautions must be observed due to bad state of the taxiways.", correctAnswer: "b", explanation: "A double white cross in the signal area indicates the aerodrome is being used by gliders and glider flights are in progress.", difficulty: "medium" },
  { id: "PLAW-M-004", sectionId: "4", question: "Selecting an alternate aerodrome the runway of this facility must be sufficiently long to allow a full stop landing from 50 ft above the threshold (jet type aircraft, dry runway) within:", optionA: "60% of the landing distance available.", optionB: "70% of the landing distance available.", optionC: "80% of the landing distance available.", optionD: "50% of the landing distance available.", correctAnswer: "a", explanation: "For landing planning, the runway must allow a full-stop landing within 60% of the landing distance available (turbojet dry).", difficulty: "medium" },
  { id: "PLAW-M-005", sectionId: "4", question: "The vehicle moving along a runway or taxiway shall as far as practical keep to the:", optionA: "right side of the runway or taxiway,", optionB: "either edge of the runway or taxiway,", optionC: "left side of the runway or taxiway.", optionD: "Nil", correctAnswer: "a", explanation: "A vehicle on a runway/taxiway shall, as far as practicable, keep to the right.", difficulty: "medium" },
  { id: "PLAW-M-006", sectionId: "4", question: "\"TODA\" take-off distance available is:", optionA: "The length of the take-off run available plus the length of clearway available (if provided).", optionB: "The length of the runway available plus the length of clearway available (if provided).", optionC: "The length of the take-off run available plus the length of the stopway and clearway (if provided).", optionD: "The length of the take-off run available plus the length of the stopway.", correctAnswer: "a", explanation: "TODA = take-off run available (TORA) + clearway.", difficulty: "medium" },
  { id: "PLAW-M-007", sectionId: "4", question: "An aerodrome with runway and centreline lighting – what is the lowest take-off minima for a Cat D aircraft?", optionA: "RVR 250 m", optionB: "RVR 200 m", optionC: "RVR 500 m", optionD: "RVR 150 m", correctAnswer: "a", explanation: "With runway and centreline lighting, the lowest take-off minima for a Cat D aircraft is RVR 250 m.", difficulty: "medium" },
  { id: "PLAW-M-008", sectionId: "4", question: "According to SA-CATS 97.07.5, for a precision approach category I runway to be classified as having full facilities, the minimum length of HI/MI approach lighting required is:", optionA: "720 m", optionB: "1 200 m", optionC: "900 m", optionD: "420 m", correctAnswer: "a", explanation: "Per SA-CATS, a Cat I precision approach runway requires a minimum RVR capability of 720 m.", difficulty: "medium" },
  { id: "PLAW-M-009", sectionId: "4", question: "Destination alternates planning minima: Aerodromes supporting straight in instrument approach and landing operation to different suitable runways. The ceiling:", optionA: "Applicable aerodrome operating minima plus an increment of 400 ft", optionB: "Applicable aerodrome operating minima plus an increment of 200 ft", optionC: "For CAT II operations at least 300 ft, for CAT III operations at least 200 ft", optionD: "For CAT II operations at least 200 ft, for CAT III operations at least 300 ft", correctAnswer: "b", explanation: "Destination-alternate planning minima = the applicable aerodrome operating minima plus a safety increment.", difficulty: "medium" },
  { id: "PLAW-M-010", sectionId: "4", question: "On a flight from Cape Town to Bloemfontein in a twin-engine aircraft that is capable of climbing to 1 500 ft on a single engine. The surface conditions at Cape Town are: - Visibility 1 500 m with runway 01 in use. For the take-off, these conditions are:", optionA: "Suitable, provided the conditions at an alternate aerodrome within 1 hour flight time on one engine are at or above landing minima", optionB: "Not suitable for take-off because in the event of an engine failure the aircraft would not be able to return for landing", optionC: "Suitable for take-off provided the conditions at an alternate within 1 hour flight time has a ceiling of at least 600 ft. a visibility of 3 200 m and an ILS available", optionD: "More information is required to answer the question", correctAnswer: "a", explanation: "The destination is suitable without an alternate only if the specified weather/runway conditions are met; otherwise a suitable alternate is required.", difficulty: "medium" },
  { id: "PLAW-M-011", sectionId: "5.1", question: "An operator shall ensure that a pilot does not operate an aeroplane as pilot-in-command unless:", optionA: "he has carried out at least three take-off and three landings as pilot flying in an aeroplane or an approved flight simulator of the type to be used, in the preceding 90 days", optionB: "he has carried out at least three flights as pilot-in-command in an aeroplane or an approved flight simulator of the type to be used, in the preceding 90 days", optionC: "he has carried out at least three take-off and three landings as pilot flying in any type of aeroplane or an approved simulator, under the supervision of an examiner, in the preceding 60 days", optionD: "he has carried out at least three take-off and three landings as pilot flying in an aeroplane or an approved flight simulator of the type to be used, in the preceding 30 days", correctAnswer: "a", explanation: "Recency: a pilot must have carried out at least three take-offs and three landings in the preceding 90 days to carry passengers.", difficulty: "medium" },
  { id: "PLAW-M-012", sectionId: "5.1", question: "The PIC of an aircraft may pick up an object:", optionA: "With approval from the Director", optionB: "Only when he/she has obtained prior written approval from the Director", optionC: "At the discretion of the PIC", optionD: "With permission from the Operator", correctAnswer: "b", explanation: "A PIC may pick up an object (e.g. by sling) only with prior written approval from the Authority.", difficulty: "medium" },
  { id: "PLAW-M-013", sectionId: "5.1", question: "At night an aircraft observes a luminous signal requesting help. To indicate that he has received these ground signals, the pilot must:", optionA: "make at least one complete turn over the group of people in difficulty.", optionB: "transmit, by luminous Morse signal, a series of the letter \"R\" using his navigational lights.", optionC: "fly over the group of people in difficulty as low as possible.", optionD: "switch his landing lights on and off twice or, if he is not so equipped, his navigation lights twice.", correctAnswer: "d", explanation: "To acknowledge a ground distress/assistance signal at night, the aircraft switches its landing lights on and off twice (or flashes nav lights).", difficulty: "medium" },
  { id: "PLAW-M-014", sectionId: "5.1", question: "If an ATC clearance is not suitable to the pilot in command of an aircraft:", optionA: "The pilot should propose another clearance to the ATC concerned.", optionB: "He may request and, if practicable, obtain an amended clearance.", optionC: "He may request another clearance and the ATC concerned has to accept the pilot request.", optionD: "The pilot has to accept the ATC clearance because it has been based on the flight plan filed with ATC.", correctAnswer: "b", explanation: "If an ATC clearance is unsuitable, the PIC may request and, if practicable, obtain an amended clearance.", difficulty: "medium" },
  { id: "PLAW-M-015", sectionId: "5.1", question: "During a night flight, an observer located in the cockpit, seeing an aircraft coming from the front right, will first see the:", optionA: "green flashing light", optionB: "red steady light", optionC: "green steady light", optionD: "white steady light", correctAnswer: "b", explanation: "A red steady light signal from ATC to an aircraft in flight means give way to other aircraft and continue circling.", difficulty: "medium" },
  { id: "PLAW-M-016", sectionId: "5.1", question: "The PIC of an aircraft shall ensure that when a flight is conducted above FL 410:", optionA: "At least one pilot wears an oxygen mask when the other pilot leaves the flight deck for any reason.", optionB: "At least one crew member wears an oxygen mask when the pilot leaves the flight deck for any reason.", optionC: "At least one passenger wears an oxygen mask when the pilot leaves the flight deck for any reason", optionD: "At least one pilot at a pilot station wears an oxygen mask when the other pilot leaves the flight deck for any reason.", correctAnswer: "d", explanation: "Above the prescribed cabin altitude, at least one pilot at the controls must wear and use an oxygen mask.", difficulty: "medium" },
  { id: "PLAW-M-017", sectionId: "5.1", question: "A pilot may not act as pilot in command carrying passengers of an aircraft unless he has, in the preceding:", optionA: "90 days carried out three take offs and landings in an aircraft of the same class and category or an approved simulator,", optionB: "six months carried out three take offs and landings in an aircraft of the same class and category or an approved simulator,", optionC: "six months carried out six take offs and landings in an aircraft of the same class and category or an approved simulator,", optionD: "Nil", correctAnswer: "a", explanation: "To carry passengers, the pilot must have made three take-offs and landings in the preceding 90 days on the same type/class.", difficulty: "medium" },
  { id: "PLAW-M-018", sectionId: "5.1", question: "Whilst flying at night, you observe the green side light of another aircraft on a relative bearing of 320 degrees at the same flight level and the bearing remains constant. You should:", optionA: "Maintain heading and speed but be prepared to take action if the other aircraft fails to give way.", optionB: "Alter heading to starboard.", optionC: "Maintain speed and alter heading to port.", optionD: "Nil", correctAnswer: "a", explanation: "Seeing the green (starboard) nav light of converging traffic, you have the other aircraft on your left and generally have right of way, but remain prepared to avoid.", difficulty: "medium" },
  { id: "PLAW-M-019", sectionId: "5.1", question: "Definition of flight time:", optionA: "The time from when the aircraft begins its take-off to when it finishes the landing", optionB: "The time from when the Aircraft is airborne to when the undercarriage touches the ground", optionC: "The time when it moves under its own power from the apron to when it parks after the end of the flight", optionD: "The time the chocks are removed, or the engine starts, to when the engine is cut at the end of the flight.", correctAnswer: "c", explanation: "Flight time is from when the aircraft first moves under its own power for take-off until it comes to rest at the end of the flight.", difficulty: "medium" },
  { id: "PLAW-M-020", sectionId: "5.1", question: "Except in emergency, no aircraft shall take off or land by night unless:", optionA: "Such aircraft is equipped with landing lights in terms of the provision of A. In which case such landing lights may be regarded as sufficient equipment for take-off and landing at night.", optionB: "The PIC of such aircraft is familiar with the aerodrome and according to his judgement sufficient means are available to assist in take-off or landing in the absence of runway lights.", optionC: "The aerodrome of take-off or landing is equipped for night flying and that the PIC has ensured that night flying facilities are available for take-off or landing.", optionD: "Nil", correctAnswer: "c", explanation: "Night take-off/landing requires the aerodrome to be equipped and lit for night operations.", difficulty: "medium" },
  { id: "PLAW-M-021", sectionId: "5.1", question: "While on a flight which is being operated for reward, a pilot deviates from the CAR. The PIC is required as soon as practical to:", optionA: "Notify the appropriate authority of the State within or over the territory of which the deviation occurred, of such deviation without delay.", optionB: "Notify the SACAA of such deviation without delay.", optionC: "Notify the appropriate authority of the State within or over the territory of which the deviation occurred, of such deviation within 24 hours.", optionD: "Nil", correctAnswer: "a", explanation: "After deviating from the rules in an emergency, the PIC must notify the appropriate authority of the State concerned.", difficulty: "medium" },
  { id: "PLAW-M-022", sectionId: "5.1", question: "In a part 135 operation, the PIC of an aircraft flying IFR must have a second in command if:", optionA: "The aeroplane is &gt; 5 700kg and certified to carry 19 or less passengers;", optionB: "has passed a single-pilot proficiency check within the previous 24 months;", optionC: "In the case of unpressurised aeroplane, not operate at a level that requires continuous use of oxygen;", optionD: "Cannot perform normal and emergency procedures without assistance.", correctAnswer: "a", explanation: "Part 135 IFR with an SIC applies where the aeroplane exceeds 5700 kg or is certified to carry 19+ passengers.", difficulty: "medium" },
  { id: "PLAW-M-023", sectionId: "5.2", question: "According to CAR 2011, when an aerodrome is selected as a destination or alternate aerodrome, the appropriate weather reports or forecasts or a combination thereof, must be at or above the applicable planning minima for a period of:", optionA: "2 hours before to 2 hours after the ETA of the aircraft at the aerodrome", optionB: "20 minutes flying time in the case of single-engine aircraft", optionC: "1 hour before to 1 hour after the ETA of the aircraft at the aerodrome", optionD: "2 hours prior to the ETA at the destination", correctAnswer: "c", explanation: "Destination-alternate weather must be within limits for the period from 1 hour before to 1 hour after the ETA.", difficulty: "medium" },
  { id: "PLAW-M-024", sectionId: "5.2", question: "When can members of the public have access to accident investigations information?", optionA: "Never", optionB: "If the investigator in-charge decides to tell them", optionC: "Only with a court order", optionD: "On completion of the final report", correctAnswer: "c", explanation: "Accident-investigation records are made available to the public only under a court order.", difficulty: "medium" },
  { id: "PLAW-M-025", sectionId: "5.2", question: "The vertical position of an aircraft at or below the transition altitude will be reported:", optionA: "as flight level.", optionB: "according pilot's choice.", optionC: "as altitude.", optionD: "as height.", correctAnswer: "c", explanation: "At or below the transition altitude, vertical position is expressed as altitude (QNH).", difficulty: "medium" },
  { id: "PLAW-M-026", sectionId: "5.2", question: "The pilot-in-command of an aircraft shall ensure that reports are made to the responsible ATSU as soon as possible of the time and level of passing each compulsory reporting point, when:", optionA: "Flying in controlled airspace only", optionB: "Flying in controlled or uncontrolled airspace", optionC: "Flying in controlled or uncontrolled airspace or on a flight for which alerting action is being provided", optionD: "Flying in controlled airspace or on a flight for which alerting action is being provided", correctAnswer: "c", explanation: "Position reports are required when flying in controlled/uncontrolled airspace or on a flight plan as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-027", sectionId: "5.2", question: "It is mandatory to notify air traffic services of revised estimated times when such times differ from the original times by more than:", optionA: "2 minutes", optionB: "3 minutes", optionC: "5 minutes", optionD: "10 minutes", correctAnswer: "b", explanation: "ATS must be notified of a revised ETA when it differs from the notified estimate by more than 3 minutes.", difficulty: "medium" },
  { id: "PLAW-M-028", sectionId: "5.2", question: "The pilot in command may depart from the prescribed Rules and Regulations in the interest of safety, when such a departure has been made the pilot must report it to the:", optionA: "Director General: Department of Transport", optionB: "nearest convenient Air Traffic Service Unit", optionC: "nearest police station", optionD: "Airport manager", correctAnswer: "b", explanation: "After departing from the rules in an emergency, the PIC notifies the nearest convenient ATS unit.", difficulty: "medium" },
  { id: "PLAW-M-029", sectionId: "5.2", question: "How many hours after being involved in an accident are you allowed to drink?", optionA: "6 hrs", optionB: "8 hrs", optionC: "12 hrs", optionD: "24 hrs", correctAnswer: "b", explanation: "Alcohol may not be consumed within 8 hours of being involved in an accident (pending any required test).", difficulty: "medium" },
  { id: "PLAW-M-030", sectionId: "5.3", question: "An applicant for a commercial pilot's license shall inter alia:", optionA: "Be not less than 18 years of age and have completed not less than 200 hours of flight time including 20 hours of cross-country flight time as PIC.", optionB: "Be not less than 17 years of age and have completed a course of approved training of 150 hours.", optionC: "Be not less than 18 years of age and have completed not less than 200 hours of flight time of which 120 hours shall be as PIC", optionD: "Nil", correctAnswer: "a", explanation: "A CPL applicant must be at least 18 years of age (and meet the prescribed experience).", difficulty: "medium" },
  { id: "PLAW-M-031", sectionId: "5.3", question: "Final reserve fuel for aeroplanes with reciprocating engines when operating under Part 91 only is:", optionA: "45 minutes if operating VFR or IFR", optionB: "30 minutes at holding speed at 1 500 feet above aerodrome elevation if operating IFR.", optionC: "30 minutes if operating VFR.", optionD: "45 minutes at holding speed at 1 500 feet above aerodrome elevation", correctAnswer: "a", explanation: "Final reserve fuel for a reciprocating-engine aeroplane = 45 minutes (VFR or IFR).", difficulty: "medium" },
  { id: "PLAW-M-032", sectionId: "5.3", question: "The holder of a pilot's licence should inform the authority of any illness which they are suffering which involves incapacity to undertake those functions to which the licence relates throughout a period of a certain number of days or m0re. The number of days is:", optionA: "60", optionB: "30", optionC: "21", optionD: "90", correctAnswer: "c", explanation: "A licence holder must inform the Authority of any illness lasting 21 days or more.", difficulty: "medium" },
  { id: "PLAW-M-033", sectionId: "5.3", question: "An applicant for the initial issue of a Commercial pilot's licence must pass the practical flight test:", optionA: "Within 36 months from the date of being notified of having passed the examination.", optionB: "Within 24 months of the date of the examination.", optionC: "Within 12 months of the date of the examination.", optionD: "Nil", correctAnswer: "a", explanation: "The skills test must be completed within 36 months of being notified of a pass in the theoretical knowledge examinations.", difficulty: "medium" },
  { id: "PLAW-M-034", sectionId: "5.3", question: "The holder of a pilot licence, when acting as co-pilot of an aircraft required to be operated with a co-pilot, shall be entitled to be credited with not more than:", optionA: "50% of the co-pilot flight time towards the total time required for a higher grade of pilot licence.", optionB: "40% of the co-pilot flight time required for a higher grade of pilot licence.", optionC: "100% of the flight time towards the total time required for a higher grade of pilot licence.", optionD: "60% of the co-pilot flight time towards the total time required for a higher grade of pilot licence.", correctAnswer: "a", explanation: "CAR 61: a co-pilot is credited with not more than 50% of the co-pilot flight time towards the total time required for a higher grade of pilot licence (full/100% credit applies to PIC-under-supervision, not ordinary co-pilot time).", difficulty: "medium" },
  { id: "PLAW-M-035", sectionId: "5.3", question: "Establishment of separate type rating for aeroplanes will be assessed on the basis of three criteria. One of these three criteria is that the aeroplane has:", optionA: "Handling characteristics that require additional flying or simulator training", optionB: "Handling characteristics that require the use of more than one crew member", optionC: "A certificate of airworthiness issued by a non-member state.", optionD: "A certificate of airworthiness issued by the manufacturer.", correctAnswer: "a", explanation: "A separate type rating is established where the aeroplane has handling characteristics requiring additional training.", difficulty: "medium" },
  { id: "PLAW-M-036", sectionId: "5.3", question: "To acquire a multi-pilot aeroplane type rating the candidate must have (inter-alia) at least the following experience:", optionA: "70 hours PIC on aeroplanes", optionB: "100 hours PIC on aeroplanes", optionC: "300 hours total time", optionD: "6 hours of training.", correctAnswer: "b", explanation: "A multi-pilot aeroplane type rating requires at least 100 hours PIC on aeroplanes.", difficulty: "medium" },
  { id: "PLAW-M-037", sectionId: "5.3", question: "During an IFR flight in VMC in controlled airspace you experience a two-way radio communication failure. You will:", optionA: "Select A7600 and continue according current flight plan to destination ;", optionB: "Descend to the flight level submitted for that portion of flight ;", optionC: "Land at the nearest suitable aerodrome and inform ATC", optionD: "Land at the nearest suitable aerodrome maintaining VMC and inform ATC ;", correctAnswer: "d", explanation: "IFR in VMC with two-way comms failure in controlled airspace: continue in VMC and land at the nearest suitable aerodrome.", difficulty: "medium" },
  { id: "PLAW-M-038", sectionId: "5.3", question: "Maintenance of competency for a CPL (Aeroplane) - in the case of a holder of a CPL where the maintenance of competency has lapsed by not more than 36 months, the licence holder shall be required to:", optionA: "comply with the initial issue requirements of Subpart 61.05.", optionB: "rewrite the Air Law examination; undergo sufficient ground and flight training at an approved ATO to reach the standard required for the revalidation check of a CPL (Aeroplane), and meet the recency requirements to act as PIC; and pass an initial licence skills test in the same category of aircraft.", optionC: "passing a revalidation check or an initial licence skills test in the same category of aircraft", optionD: "undergo sufficient ground and flight training at an approved ATO to reach the standard required for the revalidation check of a CPL (Aeroplane), and meet the recency requirements to act as PIC; and pass a revalidation check in the same category of aircraft;", correctAnswer: "d", explanation: "CPL competency maintenance: undergo sufficient ground and flight training at an approved organisation.", difficulty: "medium" },
  { id: "PLAW-M-039", sectionId: "5.3", question: "If a skills test or revalidation check is conducted within 90 days prior to the expiry date of competency then the new expiry date:", optionA: "Will be calculated from the date on which the paperwork is handed in at CAA", optionB: "Be calculated from the date of expiry of the existing licence", optionC: "Will be calculated from the end of the month in which the paperwork is handed in at CAA", optionD: "Will be calculated from the date on which the skills test took place", correctAnswer: "b", explanation: "A revalidation within 90 days of expiry is calculated from the existing expiry date.", difficulty: "medium" },
  { id: "PLAW-M-040", sectionId: "5.3", question: "An example of a class rating is:", optionA: "Aeroplane", optionB: "Helicopter", optionC: "Single engine piston aeroplane – land", optionD: "Multi engine turboprop aeroplane", correctAnswer: "c", explanation: "A class rating example is single-engine piston aeroplane (land).", difficulty: "medium" },
  { id: "PLAW-M-041", sectionId: "5.3", question: "The privileges of the holder of a commercial pilot licence-aeroplane shall be:", optionA: "to act as pilot-in command in any aeroplane engaged in operations other than commercial air transportation", optionB: "to act as pilot in command in any aeroplane engaged in commercial air transportation", optionC: "to act as pilot in command in any aeroplane certificate for single pilot operation other than in commercial air transportation", optionD: "none of the answers are correct", correctAnswer: "a", explanation: "A CPL(A) may act as PIC in any aeroplane engaged in operations other than commercial air transport, and as PIC/co-pilot in commercial air transport as privileged.", difficulty: "medium" },
  { id: "PLAW-M-042", sectionId: "5.3", question: "An applicant for a commercial pilot licence aeroplane shall have completed not less than:", optionA: "200 hours of flight time and 70 hours as pilot in command", optionB: "150 hours of flight time and 100 hours as pilot in command", optionC: "200 hours of flight time or 150 hours if completed during a course of approved training as a pilot of aeroplanes", optionD: "200 hours of flight time and 80 hours as pilot in command", correctAnswer: "c", explanation: "A CPL(A) applicant must have completed 200 hours flight time (or 150 hours if on an approved integrated course).", difficulty: "medium" },
  { id: "PLAW-M-043", sectionId: "5.3", question: "Licence holders shall not consume alcohol:", optionA: "Less than 8 hours prior to reporting time for operational duty, commence duty while the concentration of alcohol in the blood is more than 0.08 gram per millilitres.", optionB: "Less than 10 hours prior to reporting time for operational duty, commence duty while the concentration of alcohol in the blood is more than 0.02 gram per millilitres.", optionC: "Less than 12 hours prior to reporting time for operational duty, commence duty while the concentration of alcohol in the blood is more than 0.08 gram per millilitres", optionD: "Less than 8 hours prior to reporting time for operational duty, commence duty while the concentration of alcohol in the blood is more than 0.02 gram per millilitres", correctAnswer: "d", explanation: "Flight crew shall not consume alcohol less than 8 hours before reporting for duty.", difficulty: "medium" },
  { id: "PLAW-M-044", sectionId: "5.3", question: "An applicant for a Commercial Pilot Licence shall have completed in aeroplanes not less than:", optionA: "25 hours of instrument time, of which not more than 15 hours may have been acquired in a FSTD", optionB: "25 hours of instrument time, of which not more than 10 hours may have been acquired in a FSTD.", optionC: "20 hours of instrument time, of which not more than 5 hours may have been acquired in a FSTD .", optionD: "20 hours of instrument time, of which not more than 10 hours may have been acquired in a FSTD.", correctAnswer: "d", explanation: "A CPL(A) applicant must have completed 20 hours instrument time, of which not more than 10 may be instrument ground time.", difficulty: "medium" },
  { id: "PLAW-M-045", sectionId: "5.3", question: "If a licence holder is unable to perform the flight crew functions appropriate to that licence due to illness, the authority must be informed:", optionA: "if still not fit to fly when his/her current medical certificate expires", optionB: "After 21 days of consecutive \"illness\"", optionC: "as soon as possible if the illness is expected to last more than 21days", optionD: "after one calendar month of consecutive illness", correctAnswer: "b", explanation: "A licence holder unfit for 21 consecutive days of illness must notify the Authority.", difficulty: "medium" },
  { id: "PLAW-M-046", sectionId: "5.3", question: "An applicant for an IR(A) shall hold a PPL (A)including a night qualification or CPL(A) and shall have completed at least 50 hours:", optionA: "Instructional flight time as student-pilot-in-command of aeroplanes or helicopters of which at least 10 hours shall be in aeroplanes.", optionB: "50 hours cross country flight time as pilot-in-command in aeroplanes or helicopters of which at least 10 hours shall be in category of aircraft for which rating is sought.", optionC: "Cross country flight time as pilot of aeroplanes or helicopters of which at least 10 hours shall be in aeroplanes.", optionD: "Instructional flight time as student-pilot-in-command of aeroplanes.", correctAnswer: "b", explanation: "An IR(A) applicant must hold a PPL(A) with night qualification and have 50 hours cross-country PIC.", difficulty: "medium" },
  { id: "PLAW-M-047", sectionId: "5.3", question: "An applicant for an instrument rating shall have completed in aeroplanes not less than:", optionA: "10 hours of instrument flight time under instruction of which 5 may be in a FSTD", optionB: "15 hours of instrument flight time under instruction of which 10 may be in a FSTD.", optionC: "40 hours of instrument flight time under instruction of which 20 may be in a FSTD.", optionD: "20 hours of instrument flight time under instruction of which 10 may be in a FSTD.", correctAnswer: "c", explanation: "An instrument-rating applicant must complete 40 hours instrument flight time under instruction.", difficulty: "medium" },
  { id: "PLAW-M-048", sectionId: "5.3", question: "An applicant for a single pilot multi-engine aeroplane type rating shall have at least:", optionA: "6 hours theoretical knowledge and 7 hours dual flight training", optionB: "5 hours theoretical knowledge and 6 hours dual flight training", optionC: "7 hours theoretical knowledge and 6 hours dual flight training", optionD: "6 hours theoretical knowledge and 5 hours dual flight training", correctAnswer: "c", explanation: "A single-pilot multi-engine type rating requires 7 hours theoretical knowledge and 6 hours dual flight training.", difficulty: "medium" },
  { id: "PLAW-M-049", sectionId: "5.3", question: "The recent experience conditions of a captain assigned to a flight on an aircraft by an operator must not be less than:", optionA: "6 take-offs and 6 landings as pilot in command on this type of aircraft during the last 90 days", optionB: "6 take-offs and 6 landings as pilot in command on this type of aircraft during the last 6 months", optionC: "3 take-offs and 3 landings as pilot in command on this type of aircraft during the last 6 months", optionD: "3 take-offs and 3 landings as pilot in command on this type of aircraft during the last 90 days", correctAnswer: "d", explanation: "Recency on type: three take-offs and three landings as PIC on that type.", difficulty: "medium" },
  { id: "PLAW-M-050", sectionId: "5.3", question: "VFR Operating minima, establishes that, the operator shall ensure about VFR flights, that:", optionA: "for conducted VFR flights in airspace E, flight visibility at and above 3 050 m. (10 000 ft) is 5 km at least (clear of cloud)", optionB: "special VFR flights are not commenced when visibility is less than 3 km", optionC: "for conducted VFR flights in airspace B, horizontal distance from clouds is 1 000 m at least", optionD: "for conducted VFR flights in airspace F, vertical distance from clouds is 250 m at least", correctAnswer: "b", explanation: "Special VFR flights shall not be commenced when visibility is below the prescribed minimum.", difficulty: "medium" },
  { id: "PLAW-M-051", sectionId: "5.3", question: "The minimum required recency experience for a PIC or SIC for an instrument approach under IMC shall be:", optionA: "3 approaches in an aircraft or approved FSTD with reference to flight instruments only", optionB: "2 approaches in an aircraft or FSTD with reference to flight instruments only.", optionC: "3 approaches in an aircraft or FSTD with reference to flight instruments only", optionD: "2 approaches in an aircraft or approved FSTD with reference to flight instruments only.", correctAnswer: "d", explanation: "Instrument recency: two approaches in an aircraft or approved FSTD by reference to instruments (in the prescribed period).", difficulty: "medium" },
  { id: "PLAW-M-052", sectionId: "5.4", question: "If the medical examination for the CPL is suspended by a DAME, the pilot may appeal this suspension within:", optionA: "14 days", optionB: "21 days", optionC: "30 days", optionD: "90 days", correctAnswer: "a", explanation: "If a DAME suspends the medical, the pilot's privileges are suspended for 14 days pending referral.", difficulty: "medium" },
  { id: "PLAW-M-053", sectionId: "5.4", question: "The duration of the period of currency of a medical assessment shall begin on the date:", optionA: "the licence is delivered to the pilot", optionB: "the medical assessment is issued", optionC: "the licence is issued or validated", optionD: "the licence is issued or renewed", correctAnswer: "b", explanation: "The period of currency of a medical assessment is calculated from the date the assessment is issued.", difficulty: "medium" },
  { id: "PLAW-M-054", sectionId: "5.4", question: "If a medical examination reveals a medical fitness standard below that required, the CAA shall suspend that license:", optionA: "For a maximum of 14 days.", optionB: "For a period not exceeding 6 months", optionC: "Until the holder is able to show that he is able to meet the applicable medical requirements", optionD: "Nil", correctAnswer: "c", explanation: "A fitness standard below the required level means privileges are withheld until the holder shows they can meet the standard (or a special issue applies).", difficulty: "medium" },
  { id: "PLAW-M-055", sectionId: "5.4", question: "After an accident or incident, the public will have access to the information collected, including statements, communications with ATC, medical reports of persons involved, information obtained from the flight data recorder:", optionA: "When the investigation is completed;", optionB: "If requested from the Director of Investigations;", optionC: "If requested from the Director of Civil Aviation;", optionD: "Only if a court of law determines that their public disclosure outweighs the adverse domestic and international impact.", correctAnswer: "d", explanation: "Accident/incident information is released to the public only if a court of law determines its disclosure is in the public interest.", difficulty: "medium" },
  { id: "PLAW-M-056", sectionId: "5.4", question: "Class 1 medical will be issued:", optionA: "For a CPL, 6 months if the candidate is under 40 years of age for single pilot operation;", optionB: "For a CPL over 40 years of age, for 12 months, unless he or she operates in a single pilot operation, then it is issued for 6 months;", optionC: "For an ATP in any multi-crew commercial operation it will be issued for 6 months;", optionD: "For a CPL or ATP in any multi-crew operation it will be issued for 6 months if the candidate is over 60 years.", correctAnswer: "d", explanation: "A Class 1 medical is required for a CPL/ATPL; in multi-crew operations its validity/period applies as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-057", sectionId: "5.4", question: "Dangerous goods to be transported includes medical equipment. This will be permitted in the cabin:", optionA: "If required by a passenger in the cabin", optionB: "Will not be permitted if it is for a sick animal", optionC: "Must be declared to the PIC and the PIC will decide if it is to be permitted", optionD: "Only applies to a pacemaker", correctAnswer: "a", explanation: "Dangerous goods may be carried for an operational need such as medical equipment required by a passenger, subject to the rules.", difficulty: "medium" },
  { id: "PLAW-M-058", sectionId: "5.5", question: "Which procedure do you follow if during an IFR flight in VMC you have two way communication failure?", optionA: "Continue the flight at the assigned level and route; start approach at your ETA.", optionB: "Maintain your assigned level and route and land at the nearest aerodrome that has VMC conditions.", optionC: "Continue the flight maintaining VMC and land as soon as practicable.", optionD: "Return to the aerodrome of departure.", correctAnswer: "c", explanation: "IFR in VMC with two-way comms failure: continue the flight maintaining VMC and land as soon as practicable.", difficulty: "medium" },
  { id: "PLAW-M-059", sectionId: "5.5", question: "The vertical IFR separation minimum being applied by ATC within a controlled airspace below FL 290 is:", optionA: "2000 feet (600 m).", optionB: "500 feet (150 m).", optionC: "2500 feet (750 m).", optionD: "1000 feet (300 m).", correctAnswer: "d", explanation: "The IFR vertical separation minimum applied by ATC (below RVSM levels) is 1000 ft (300 m).", difficulty: "medium" },
  { id: "PLAW-M-060", sectionId: "5.5", question: "At night when flying by IFR and except when taking-off or landing, the minimum height above the height of the highest obstacle at 5 000 feet or below and within 5 NM of the aircraft is:", optionA: "1 500 ft.", optionB: "1 000 ft.", optionC: "2 000 ft.", optionD: "Nil", correctAnswer: "b", explanation: "At night under IFR (except take-off/landing), the aircraft must be at least 1000 ft above the highest obstacle within the prescribed radius.", difficulty: "medium" },
  { id: "PLAW-M-061", sectionId: "5.5", question: "Preparing an IFR flight from controlled into or through uncontrolled airspace, the FL to be selected in accordance with semi-circular rules depends on:", optionA: "The Magnetic Track and whether he is flying in VMC or IMC.", optionB: "The Magnetic track only.", optionC: "The compass heading and whether he is flying in VMC or IMC.", optionD: "Only on whether he is flying in IMC or VMC.", correctAnswer: "b", explanation: "On an IFR leg from controlled into uncontrolled airspace, the magnetic track is the item flight-planned for that segment.", difficulty: "medium" },
  { id: "PLAW-M-062", sectionId: "5.5", question: "Whilst taxiing at an uncontrolled airfield, the pilot observes an aircraft converging from the right. The pilot should:", optionA: "Continue to taxi.", optionB: "Slow down or stop and allow the other aircraft right of way.", optionC: "Continue to taxi if on an IFR flight plan.", optionD: "Nil", correctAnswer: "b", explanation: "When taxiing and another aircraft has right of way, slow down or stop and give way.", difficulty: "medium" },
  { id: "PLAW-M-063", sectionId: "5.5", question: "As far as the planning minima for IFR flights is concerned, in which of the following cases shall the cloud ceiling be taken into account?", optionA: "When the only approaches are VOR, VOR/DME, NDB or circling approaches", optionB: "In all cases", optionC: "When an IFR flight is planned to an aerodrome en route where an approach can be made to encounter VMC and then continued in VMC to the destination", optionD: "When the only approaches available are non-precision or circling approaches", correctAnswer: "d", explanation: "An alternate/planning requirement is triggered when only non-precision or circling approaches are available (weather margins increase).", difficulty: "medium" },
  { id: "PLAW-M-064", sectionId: "5.5", question: "The communication failure procedure require that flights where VMC cannot be maintained and in controlled airspace:", optionA: "Shall proceed according to the current flight plan.", optionB: "If cleared to a flight level below that in the flight plan, if terrain permits maintain this level for 7 minutes, then climb to flight plan level.", optionC: "If cleared to a flight level below that in the flight plan, if terrain permits maintain this level for 3 minutes then climb to flight plan level", optionD: "Nil", correctAnswer: "b", explanation: "On comms failure, if cleared to a level below the flight-plan level, maintain the last assigned level as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-065", sectionId: "5.5", question: "Definition of \"Transition altitude\":", optionA: "The Transition Altitude specified at major airports, and is where the pilot is expected to set the QNH in the subscale of the altimeter", optionB: "The Transition altitude is always at 18000 feet and at this point in the climb the pilot will set 1013 in the subscale", optionC: "The Transition altitude is designated at major airports and is given to the pilot on the ATIS; this is where he or she is expected to contact ATC after departure", optionD: "The Transition Altitude is designated at major airports and is where the pilot will set 1013 on the climb out to a flight level.", correctAnswer: "d", explanation: "Transition altitude is the altitude at/below which vertical position is controlled by reference to altitude (QNH); it is designated per aerodrome.", difficulty: "medium" },
  { id: "PLAW-M-066", sectionId: "5.5", question: "Except when a clearance is obtained from an ATC unit, a VFR flight cannot enter or leave a control zone when ceiling is less than:", optionA: "1 500 feet or visibility is less than 5 km", optionB: "1 000 feet or visibility is less than 5 km", optionC: "2 000 feet or visibility is less than 5 km", optionD: "1 000 feet or visibility is less than 8 km", correctAnswer: "a", explanation: "VFR flight in the relevant airspace requires at least 1500 ft (or the prescribed clearance) and 5 km visibility; below that, special VFR/clearance is needed.", difficulty: "medium" },
  { id: "PLAW-M-067", sectionId: "5.5", question: "The speed limitation for VFR flights inside ATS airspace classified as C, when flying below 3.050 m (10.000 ft) AMSL, is:", optionA: "250 KT IAS", optionB: "250 KT TAS", optionC: "Not applicable", optionD: "240 KT IAS", correctAnswer: "a", explanation: "Below FL100, the IAS limit (incl. VFR in the relevant ATS airspace) is 250 kt.", difficulty: "medium" },
  { id: "PLAW-M-068", sectionId: "5.5", question: "An aircraft flying above the sea between 4 500 feet MSL and 9 000 feet MSL outside controlled airspace under VFR, must remain on principle at least:", optionA: "1 500 m horizontally, 1000 feet vertically from clouds; 5 km visibility.", optionB: "1500 m horizontally, 1000 feet vertically from clouds; 8 km visibility.", optionC: "Clear of clouds and in sight of the surface; 8 km visibility.", optionD: "2 000 feet horizontally, 1000 feet vertically from clouds; 5 km visibility.", correctAnswer: "a", explanation: "Between 4500 ft and FL100, VFR requires 1500 m horizontal and 1000 ft vertical clearance from cloud and 5 km visibility.", difficulty: "medium" },
  { id: "PLAW-M-069", sectionId: "5.5", question: "Supplemental oxygen is used to:", optionA: "provide people on board with oxygen during a cabin depressurisation", optionB: "protect a crew who fights a fire", optionC: "provide with oxygen passengers who might require it, following a cabin depressurisation", optionD: "assist a passenger with breathing disorders", correctAnswer: "a", explanation: "Supplemental oxygen provides crew/passengers with oxygen during a cabin depressurisation or at high cabin altitude.", difficulty: "medium" },
  { id: "PLAW-M-070", sectionId: "5.5", question: "On landing on an isolated field, the captain of a turbojet engine aircraft must mandatorily have a minimum quantity of fuel and lubricant sufficient for flying during:", optionA: "2 hours with normal cruising consumption", optionB: "2 hours at holding flight speed and 1500 ft", optionC: "30 minutes at holding flight speed and 1500 ft", optionD: "30 minutes with normal cruising consumption", correctAnswer: "a", explanation: "For an isolated destination (turbojet), additional fuel = 2 hours at normal cruise consumption (no alternate available).", difficulty: "medium" },
  { id: "PLAW-M-071", sectionId: "5.5", question: "A second sensitive altimeter must be installed on board aeroplanes operated under Part 135 for:", optionA: "All IFR flights", optionB: "All VFR flight", optionC: "All flights above 10 000 ft", optionD: "All flight", correctAnswer: "a", explanation: "A second (standby) sensitive altimeter is required for all IFR flights (as prescribed).", difficulty: "medium" },
  { id: "PLAW-M-072", sectionId: "5.5", question: "The transition altitude of an aerodrome should not be below:", optionA: "1000 ft", optionB: "2000 ft", optionC: "3000 ft", optionD: "4000 ft", correctAnswer: "c", explanation: "The transition altitude of an aerodrome should not be below 3000 ft.", difficulty: "medium" },
  { id: "PLAW-M-073", sectionId: "5.5", question: "A commander shall ensure that the amount of usable fuel remaining in flight is not less than the fuel required to proceed to an aerodrome where a safe landing can be made with:", optionA: "fuel to fly 20 minutes at best range speed.", optionB: "15 minutes of remaining fuel.", optionC: "final reserve fuel remaining.", optionD: "fuel to hold 30 minutes at 1500 ft above the aerodrome.", correctAnswer: "c", explanation: "Usable fuel on landing must not be less than the final reserve fuel.", difficulty: "medium" },
  { id: "PLAW-M-074", sectionId: "5.5", question: "SA radio communication failure procedures for flights under IFR in IMC:", optionA: "Only distinguish between flights IFR encountering VMC conditions and those that don't", optionB: "Assume that flights will route towards the nearest area with VMC as soon as possible", optionC: "Assume only procedural separation between aircraft", optionD: "Distinguish between flights in airspace where an ATS surveillance system is used in the provision of ATC and flights in airspace where it is not", correctAnswer: "d", explanation: "The SA comms-failure IFR/IMC procedure distinguishes between airspace where an ATS surveillance service is or is not provided.", difficulty: "medium" },
  { id: "PLAW-M-075", sectionId: "5.5", question: "In the event of communication failure the squawk code to be selected on the transponder is:", optionA: "7600", optionB: "7500", optionC: "Maintain assigned squawk code and ident", optionD: "7700", correctAnswer: "a", explanation: "On comms failure, squawk 7600.", difficulty: "medium" },
  { id: "PLAW-M-076", sectionId: "5.5", question: "The minimum height an aircraft may fly over an airfield:", optionA: "500 ft", optionB: "1000 ft", optionC: "1500 ft", optionD: "2000ft", correctAnswer: "d", explanation: "Minimum height over an aerodrome (not taking off/landing) is 2000 ft, unless otherwise authorised.", difficulty: "medium" },
  { id: "PLAW-M-077", sectionId: "5.5", question: "Flying from A to B at FL 90 in IMC. En route you fly overhead an aerodrome with a QNH of 1001:", optionA: "Change your altimeter to QNH", optionB: "It is of no concern to you as you are flying overhead", optionC: "Advise ATC that you are flying on QNE", optionD: "Be vigilant, your actual altitude is lower than the indicated FL", correctAnswer: "d", explanation: "Flying in IMC over an aerodrome with a lower QNH than set, be vigilant: your true altitude is lower than indicated (temperature/pressure error).", difficulty: "medium" },
  { id: "PLAW-M-078", sectionId: "5.5", question: "Psychoactive substances:", optionA: "Any substance with psychotropic effects including cannabis, cocaine, tobacco and caffeine", optionB: "Any substance with psychotropic effects including cannabis &amp; cocaine but excluding tobacco and caffeine", optionC: "Any substance without psychotropic effects including cannabis &amp; cocaine but excluding tobacco and caffeine", optionD: "Any prescribed medication taken strictly under medical supervision", correctAnswer: "b", explanation: "Psychoactive (psychoactive) substances are substances with psychotropic effects including cannabis and cocaine but excluding tobacco and caffeine.", difficulty: "medium" },
  { id: "PLAW-M-079", sectionId: "5.5", question: "South African altimeter setting procedures have to be complied with:", optionA: "By only IFR aircraft", optionB: "By only VFR traffic", optionC: "By all aircraft operating in level flight at or above 1500 ft above ground or water", optionD: "By all aircraft operating in level flight at or below 1500 ft above ground or water", correctAnswer: "c", explanation: "SA altimeter-setting procedures apply to all aircraft operating in level flight at or above the transition level / as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-080", sectionId: "5.5", question: "Aircraft \"A\" with an ATC clearance is flying in VMC conditions within a control area. Aircraft \"B\" with no ATC clearance is approaching at approximately the same altitude and on a converging course. Which has the right of way?", optionA: "Aircraft \"A\" if \"B\" is on its right", optionB: "Aircraft \"A\" regardless of the direction which \"B\" is approaching", optionC: "Aircraft \"B\" regardless of the direction \"A\" is approaching", optionD: "Aircraft \"B\" if \"A\" is on its left", correctAnswer: "d", explanation: "Converging IFR traffic in VMC: give way to the aircraft on the right (aircraft B gives way if A is on its left).", difficulty: "medium" },
  { id: "PLAW-M-081", sectionId: "5.5", question: "Repetitive flight plans (RPL's) shall not be used for flights operated regularly on the same day(s) of consecutive weeks and:", optionA: "On at least 20 days consecutively", optionB: "On at least 20 occasions", optionC: "On at least ten occasions or every day over a period of at least ten consecutive days", optionD: "On at least ten occasions or every day over a period of at least 20 consecutive days", correctAnswer: "c", explanation: "Repetitive flight plans (RPLs) require the flight to operate regularly (e.g. on at least ten occasions or daily over a period).", difficulty: "medium" },
  { id: "PLAW-M-082", sectionId: "5.5", question: "For controlled traffic that shall be separated in the vicinity of an airport, separation minima may be reduced:", optionA: "At the discretion of the air traffic controller", optionB: "If the commander of the involved aircraft so requests", optionC: "Only if the air traffic controller has the involved aircraft in sight", optionD: "When the commander in the following aircraft has the preceding aircraft in sight and is able to maintain own separation", correctAnswer: "d", explanation: "On final approach, the following aircraft gives way; where the commander behind has the preceding aircraft in sight, separation responsibility applies as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-083", sectionId: "5.5", question: "What are the controlled IFR separation methods applied by ATC?", optionA: "Vertical, horizontal and longitudinal separation.", optionB: "Time separation and track separation.", optionC: "Composite separation.", optionD: "Vertical, horizontal and composite separation.", correctAnswer: "d", explanation: "ATC applies vertical, horizontal and composite separation methods to controlled IFR traffic.", difficulty: "medium" },
  { id: "PLAW-M-084", sectionId: "5.5", question: "Minimum height when circling over a crowd of people is:", optionA: "1 000 ft", optionB: "2 000 ft", optionC: "3 000 ft", optionD: "not permitted", correctAnswer: "c", explanation: "Minimum height when circling over an open-air assembly/crowd is 3000 ft (or the prescribed obstacle clearance, whichever is higher).", difficulty: "medium" },
  { id: "PLAW-M-085", sectionId: "5.5", question: "An aircraft flown in accordance with VFR shall not be required to comply with flight levels according to magnetic track when flown at a height (above the surface) of less than:", optionA: "3 000 ft", optionB: "2 000 ft", optionC: "1 000 ft", optionD: "1 500 ft", correctAnswer: "d", explanation: "A VFR aircraft need not comply with certain requirements when operating at or below 1500 ft as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-086", sectionId: "5.5", question: "Transition from altitude to flight level, and vice-versa is done:", optionA: "at transition level during climb and transition altitude during descent.", optionB: "only at transition altitude.", optionC: "only at transition level.", optionD: "at transition altitude during climb and transition level during descent.", correctAnswer: "d", explanation: "Transition from altitude to flight level is done at the transition altitude on climb and at the transition level on descent.", difficulty: "medium" },
  { id: "PLAW-M-087", sectionId: "5.5", question: "At airfields where there is no published transition altitude, for arriving or departing IMC flights, the transition altitude shall be:", optionA: "1 000 agl", optionB: "2 000 agl", optionC: "3 000 agl", optionD: "the lowest safe cruising altitude", correctAnswer: "d", explanation: "Where no transition altitude is published, use the lowest safe (minimum) cruising altitude for the setting change.", difficulty: "medium" },
  { id: "PLAW-M-088", sectionId: "5.5", question: "Change from IFR to VFR will always take place:", optionA: "on the initiative of the aircraft commander", optionB: "at the clearance limit, irrespective of the weather conditions", optionC: "as instructed by an air traffic control unit", optionD: "when the aircraft is leaving controlled airspace during VMC", correctAnswer: "a", explanation: "A change from IFR to VFR is always on the initiative of the aircraft commander (ATC must be advised).", difficulty: "medium" },
  { id: "PLAW-M-089", sectionId: "5.5", question: "VFR requirements on a control zone include a minimum visibility of:", optionA: "1 000 m", optionB: "5 000 m", optionC: "3 000 m", optionD: "2 000 m", correctAnswer: "b", explanation: "VFR in a control zone requires a minimum flight visibility of 5000 m (5 km).", difficulty: "medium" },
  { id: "PLAW-M-090", sectionId: "5.5", question: "A life jacket is mandatory for any passenger on board an aircraft flying away from the shore by more than:", optionA: "400 NM", optionB: "50 NM", optionC: "100 NM", optionD: "200 NM", correctAnswer: "b", explanation: "A life jacket is mandatory for occupants of an aircraft flying beyond 50 NM (or gliding distance) from land over water, as prescribed.", difficulty: "medium" },
  { id: "PLAW-M-091", sectionId: "5.5", question: "On board a pressurized aircraft, a flight shall be undertaken only if the aircraft is provided with an oxygen reserve enabling all the crew members and part of the passengers to be supplied with oxygen in the event of a cabin depressurization, throughout the flight period, during which the pressure altitude is greater than:", optionA: "12 000 ft.", optionB: "11 000 ft.", optionC: "10 000 ft.", optionD: "13 000 ft.", correctAnswer: "a", explanation: "A flight in a pressurised aircraft may be undertaken only if it can maintain a cabin altitude not exceeding 12000 ft (with supplemental-oxygen provisions).", difficulty: "medium" },
  { id: "PLAW-M-092", sectionId: "5.6", question: "SA CAR Part 139 refers to:", optionA: "Aerodromes and Heliports", optionB: "Airspaces and Air Traffic Services", optionC: "Air ambulance services", optionD: "Air Transportation: Small aeroplanes", correctAnswer: "a", explanation: "SA CAR Part 139 covers Aerodromes and Heliports.", difficulty: "medium" },
  { id: "PLAW-M-093", sectionId: "5.7", question: "No person shall operate an aeroplane, unless such aeroplane is equipped with a flotation device or life jacket containing a survivor locator light for each person on board:", optionA: "when flying over land &amp; beyond gliding distance from water", optionB: "when flying over water &amp; beyond gliding distance from land;", optionC: "when flying beyond 50 nautical miles from land", optionD: "when flying beyond 30 nautical miles from land;", correctAnswer: "b", explanation: "Life jackets are required for over-water flight beyond gliding distance from land suitable for an emergency landing.", difficulty: "medium" },
];

export function getPPLAirLawMinedBySection(sectionId: string): AirLawQuestion[] {
  return PPL_AIRLAW_MINED_QUESTIONS.filter((q) => q.sectionId === sectionId);
}